5);padding:11px 17px;color:#e4efeb;font:9px 'DM Mono';letter-spacing:.5px;transition:.25s}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:absolute;z-index:20;inset:0;background:rgba(3,10,14,.67);backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;padding:20px}.modal-backdrop.open{display:flex}.spawn-modal{width:min(760px,100%);background:#0b1a24;border:1px solid rgba(213,237,240,.17);box-shadow:0 25px 100px #02080c;max-height:calc(100vh - 40px);overflow:auto}.modal-head{padding:21px 24px 16px;display:flex;justify-content:space-between;border-bottom:1px solid var(--line)}.eyebrow{font:8px 'DM Mono';color:#95a9b1;letter-spacing:1.3px}.modal-head h1{font-size:22px;letter-spacing:-.7px;margin:7px 0 0}.modal-head h1 span{color:var(--lime)}.close-btn,.close-help{border:1px solid var(--line);background:transparent;width:30px;height:30px;font-size:19px;color:#adc0c6}.modal-body{display:grid;grid-template-columns:1.05fr .95fr;gap:25px;padding:20px 24px}.field-title{font:8px 'DM Mono';letter-spacing:1px;color:#dce7e9;padding-bottom:10px;border-bottom:1px solid var(--line);margin-bottom:11px}.field-title span{float:right;color:#728994;font-size:8px}.fleet-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.fleet-card{min-height:84px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.025);text-align:left;padding:9px;position:relative;transition:.15s}.fleet-card:hover,.fleet-card.selected{border-color:var(--lime);background:rgba(200,243,107,.07)}.fleet-art{font-size:19px;color:var(--lime);display:block;height:27px}.fleet-card strong{display:block;font-size:9px}.fleet-card small{display:block;color:#869ba4;font:8px 'DM Mono';margin-top:4px}.fleet-card .select-check{position:absolute;top:8px;right:8px;color:var(--lime);font-size:12px;opacity:0}.fleet-card.selected .select-check{opacity:1}.fleet-note{font-size:8px;line-height:1.7;color:#80949d;margin-top:12px}.range-row{display:block;margin:11px 0 13px}.range-row>span{font-size:9px;color:#b9c9ce;display:flex;justify-content:space-between}.range-row b{font:9px 'DM Mono';font-weight:400;color:#e8f0ee}.range-row input[type=range]{width:100%;height:3px;margin:11px 0 0;display:block;accent-color:var(--lime)}select{background:#10232d;border:1px solid var(--line);color:#dce9e9;font:9px 'DM Mono';padding:6px 7px;min-width:100px}.good-status{color:var(--lime)!important}.condition-title{margin-top:20px}.confirm-button{height:40px;width:100%;border:0;background:var(--lime);color:#17220d;font-size:9px;font-weight:800;letter-spacing:1px;margin-top:11px;text-align:left;padding:0 12px}.confirm-button span{float:right;font-size:15px}.modal-foot{height:36px;border-top:1px solid var(--line);padding:0 24px;display:flex;align-items:center;justify-content:space-between;color:#80949e;font:8px 'DM Mono';letter-spacing:.6px}.help-panel{position:absolute;z-index:22;right:64px;top:73px;width:310px;display:none;background:rgba(8,22,31,.96);padding:17px;border:1px solid var(--line);box-shadow:0 15px 40px #142126}.help-panel.open{display:block}.help-panel strong{font:9px 'DM Mono';letter-spacing:1px;color:var(--lime)}.help-panel p{font-size:9px;line-height:1.7;color:#b9c9ce;margin:12px 0 0}.help-panel kbd{font-size:7px}.close-help{float:right;border:0;width:20px;height:20px;line-height:15px}.control-pad{display:none}
