ct-body h2{font-size:13px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.16;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5c6');scene.fog=new THREE.FogExp2('#a9c5c6',.000085);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,12000);camera.position.set(700,470,1100);
const hemi=new THREE.HemisphereLight('#d9f0f3','#52645a',2.1);scene.add(hemi);const sun=new THREE.DirectionalLight('#fff0d6',3.4);sun.position.set(-900,1300,400);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-1600;sun.shadow.camera.right=1600;sun.shadow.camera.top=1600;sun.shadow.camera.bottom=-1600;scene.add(sun);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={ground:mat('#899b82'),grass:mat('#718872'),road:mat('#485354'),roadline:mat('#d7d0ac'),roof:mat('#8a9088'),glass:mat('#243e4b',.24,.5),concrete:mat('#a8aaa0'),water: new THREE.MeshStandardMaterial({color:'#508c96',roughness:.36,metalness:.18}),white:mat('#e4e6df',.42,.15),dark:mat('#26313a',.6,.2),lime:mat('#b9e65e',.38,.1)};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(9000,9000),mats.ground);ground.rotation.x=-Math.PI/2;ground.position.y=-4;ground.receiveShadow=true;scene.add(ground);
// Coastal water and a gently curving shoreline
const water=new THREE.Mesh(new THREE.PlaneGeometry(9000,2200),mats.water);water.rotation.x=-Math.PI/2;water.position.set(0,-3.6,-3700);scene.add(water);
const landEdge=new THREE.Mesh(new THREE.PlaneGeometry(9000,250),mat('#c5bfa4'));landEdge.rotation.x=-Math.PI/2;landEdge.position.set(0,-3.7,-2500);scene.add(landEdge);
function box(parent,geo,material,pos,scale,cast=true){const m=new THREE.Mesh(geo,material);m.position.set(...pos);if(scale)m.scale.set(...scale);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
// Urban district: varied mid-rise blocks, rooftop detail, streets, trees
const city=new THREE.Group();scene.add(city);let seed=92;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
const buildingMats=['#c5c1b4','#aeb7b2','#d0c8b7','#8d9b9b','#b8b8aa','#9ca9a8'].map(c=>mat(c,.88));
for(let ix=-9;ix<=9;ix++)for(let iz=-8;iz<=7;iz++){
 if(Math.abs(ix)<3&&iz>-2&&iz<4)continue;const x=ix*175+(rand()-.5)*36,z=iz*180+(rand()-.5)*36;
 const w=75+rand()*55,d=70+rand()*55,h=24+rand()*95;
 const b=new THREE.Group();b.position.set(x,-4,z);city.add(b);
 box(b,new THREE.BoxGeometry(w,h,d),buildingMats[Math.floor(rand()*buildingMats.length)],[0,h/2,0],[1,1,1]);
 box(b,new THREE.BoxGeometry(w*.55,2,d*.58),mat('#737f7d'),[0,h+1,0],[1,1,1],false);
 if(rand()>.55)box(b,new THREE.BoxGeometry(w*.32,7,d*.3),buildingMats[Math.floor(rand()*buildingMats.length)],[0,h+5,0],[1,1,1]);
 // slim window bands
 const winMat=mat(rand()>.45?'#48636a':'#d2c8a9',.33,.16);
 for(let y=9;y<h-5;y+=10){box(b,new THREE.BoxGeometry(w*.86,.8,.25),winMat,[0,y,d/2+.13],[1,1,1],false);box(b,new THREE.BoxGeometry(.25,.8,d*.82),winMat,[w/2+.12,y,0],[1,1,1],false)}
}
// Grid streets with pale lane dashes
for(let i=-9;i<=9;i++){
 let roadX=i*175;box(city,new THREE.BoxGeometry(15,.16,3100),mats.road,[roadX,-3.7,-360],[1,1,1],false);
 for(let z=-1820;z<1100;z+=85)box(city,new THREE.BoxGeometry(.48,.2,25),mats.roadline,[roadX,-3.59,z],[1,1,1],false);
}
for(let i=-8;i<=7;i++){const rz=i*180;box(city,new THREE.BoxGeometry(3100,.16,13),mats.road,[0,-3.7,rz],[1,1,1],false);for(let x=-1490;x<1500;x+=85)box(city,new THREE.BoxGeometry(25,.2,.48),mats.roadline,[x,-3.59,rz],[1,1,1],false)}
// Airport apron and runway with markings
const airport=new THREE.Group();scene.add(airport);box(airport,new THREE.BoxGeometry(1700,.7,1250),mats.concrete,[-250,-3.4,1160],[1,1,1],false);
box(airport,new THREE.BoxGeometry(190,.8,1490),mat('#353f43'),[-300,-3,1220],[1,1,1],false);
box(airport,new THREE.BoxGeometry(3,.8,1450),mat('#eee8cc'),[-300,-2.55,1220],[1,1,1],false);
for(let z:=-2; z<1; z++){} 
for(let z=510;z<1940;z+=92)box(airport,new THREE.BoxGeometry(2,.8,43),mat('#ecebdc'),[-300,-2.5,z],[1,1,1],false);
for(const x of [-387,-213])for(const z of [525,1890]){box(airport,new THREE.BoxGeometry(22,.7,9),mat('#eee9dc'),[x,-2.5,z],[1,1,1],false)}
// Terminal glass facade and roof
const terminal=new THREE.Group();terminal.position.set(-255,-3,300);airport.add(terminal);box(terminal,new THREE.BoxGeometry(440,36,95),mat('#b8bdb5'),[0,18,0]);box(terminal,new THREE.BoxGeometry(448,4,103),mat('#555f60'),[0,38,0]);box(terminal,new THREE.BoxGeometry(420,20,2),mat('#42616a',.24,.25),[0,21,48]);
for(let x=-190;x<=190;x+=38)box(terminal,new THREE.BoxGeometry(2,22,3),mat('#a9b5b2',.4,.4),[x,21,50]);
// Park trees for color and scale
const trees=new THREE.Group();scene.add(trees);for(let i=0;i<180;i++){const x=(rand()-.5)*3300,z=(rand()-.5)*3000;if(Math.abs(x)<570&&z>500&&z<1950)continue;const trunk=box(trees,new THREE.CylinderGeometry(1.3,1.8,11,6),mat('#695746'),[x,1.5,z],[1,1,1],false);const crown=box(trees,new THREE.IcosahedronGeometry(7+rand()*6,1),mat(rand()>.5?'#5e8068':'#769070'),[x,10+rand()*3,z],[1,1.1,1],false)}
// Aircraft library, detailed procedural airframe with variant geometry
const fleet=[
 {id:'a320',name:'Airbus A320',type:'NARROW BODY · TWIN JET',span:35.8,length:37.6,mass:73500,thrust:240000,speed:210,seats:150,color:'#e6eceb',tail:'#86bd79',engines:2,shape:'jet'},
 {id:'b738',name:'Boeing 737-800',type:'NARROW BODY · TWIN JET',span:35.8,length:39.5,mass:79000,thrust:250000,speed:225,seats:162,color:'#f0f0e9',tail:'#4e8391',engines:2,shape:'jet'},
 {id:'b747',name:'Boeing 747-400',type:'WIDE BODY · FOUR ENGINE',span:64.4,length:70.7,mass:396000,thrust:1012000,speed:250,seats:416,color:'#e7ece9',tail:'#c39348',engines:4,shape:'jumbo'},
 {id:'e175',name:'Embraer E175',type:'REGIONAL · TWIN JET',span:26,length:31.7,mass:38000,thrust:136000,speed:190,seats:88,color:'#e9e9e1',tail:'#bd715c',engines:2,shape:'regional'}
];
const aircraft=[];let selected=null,controlled=null,weatherMode=0;
function makePlane(data,conditions={}){
 const s=data.span/36, length=data.length/38;const group=new THREE.Group();group.scale.setScalar(s);
 const bodyMat=mat(data.color,.38,.16),wingMat=mat('#d2d9d4',.43,.2),accent=mat(data.tail,.36,.15),dark=mat('#26333a',.3,.28),rubber=mat('#202526',.9);
 // fuselage tapered segmented silhouette using lathe profile around aircraft local Y axis, then align to X
 const profile=[new THREE.Vector2(.03,-data.length*.49/ s),new THREE.Vector2(.45,-data.length*.45/s),new THREE.Vector2(.86,-data.length*.32/s),new THREE.Vector2(1,-data.length*.12/s),new THREE.Vector2(1,data.length*.19/s),new THREE.Vector2(.82,data.length*.37/s),new THREE.Vector2(.45,data.length*.47/s),new THREE.Vector2(.02,data.length*.5/s)];
 const fus=new THREE.Mesh(new THREE.LatheGeometry(profile,14),bodyMat);fus.rotation.z=-Math.PI/2;fus.castShadow=true;fus.receiveShadow=true;group.add(fus);
 // wings, custom tapered planform
 const wingLen=data.span*.49/s, wingRoot=data.shape==='jumbo'?10.5:7.8, wingTip=data.shape==='regional'?2.4:3.1;
 function makeWing(sign){const shape=new THREE.Shape();shape.moveTo(-wingRoot*.55,-2);shape.lineTo(-wingLen,-wingTip*.1);shape.lineTo(-wingLen*.96,wingTip*.55);shape.lineTo(wingRoot*.55,wingRoot*.47);shape.lineTo(wingRoot*.5,wingRoot*.68);shape.lineTo(-wingLen*.91,wingTip);shape.lineTo(-wingLen*.84,wingTip*1.35);shape.lineTo(wingRoot*.5,wingRoot*.77);shape.lineTo(wingRoot*.52,3);shape.closePath();const m=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:.42,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:.13,bevelThickness:.1}),wingMat);m.rotation.x=Math.PI/2;m.position.set(0,0,sign*1.5);m.castShadow=true;group.add(m);const flap=box(group,new THREE.BoxGeometry(wingLen*.42,.23,.55),accent,[wingLen*.2,-.18,sign*(wingRoot*.61)],[1,1,1]);flap.rotation.y=sign*.025}
 makeWing(1);makeWing(-1);
 // horizontal stabilizers and rudder
 const tailplane=box(group,new THREE.BoxGeometry(data.span*.31/s,.3,4.1),wingMat,[-data.length*.37/s,0,0]);tailplane.rotation.y=.02;
 const fin=box(group,new THREE.BoxGeometry(5.2,.35,7.8),accent,[-data.length*.37/s,3.8,0]);fin.rotation.z=-.42;
 // raised hump on 747 upper forward fuselage
 if(data.shape==='jumbo'){const hump=box(group,new THREE.CylinderGeometry(.8,.8,data.length*.17/s,12),bodyMat,[data.length*.14/s,.85,0],[1,1,1]);hump.rotation.z=Math.PI/2;}
 // engines hanging beneath wing; shared nested assembly for failure/damage
 const engineGroups=[];const offsets=data.engines===4?[-wingRoot*.72,-wingRoot*.42,wingRoot*.42,wingRoot*.72]:[-wingRoot*.58,wingRoot*.58];
 for(const z of offsets){const eng=new THREE.Group();eng.position.set(data.shape==='jumbo'?2.3:1.4,-1.2,z);group.add(eng);const radius=data.shape==='jumbo'?1.48:1.16;
  const nac=new THREE.Mesh(new THREE.CylinderGeometry(radius*.82,radius,6.8,16),bodyMat);nac.rotation.z=Math.PI/2;nac.castShadow=true;eng.add(nac);
  const lip=new THREE.Mesh(new THREE.TorusGeometry(radius*.82,.13,7,18),dark);lip.rotation.y=Math.PI/2;lip.position.x=3.35;eng.add(lip);
  const fan=new THREE.Mesh(new THREE.CircleGeometry(radius*.62,14),dark);fan.rotation.y=Math.PI/2;fan.position.x=3.37;eng.add(fan);
  const pylon=box(eng,new THREE.BoxGeometry(3.2,1.5,1.5),wingMat,[-.2,1.25,0]);pylon.rotation.z=.16;engineGroups.push(eng)}
 // cockpit glazing and nose windows
 const cockpit=new THREE.Mesh(new THREE.SphereGeometry(.95,12,8),mat('#253a46',.2,.4));cockpit.scale.set(1.4,.46,.91);cockpit.position.set(data.length*.43/s,.2,0);group.add(cockpit);
 // cabin window rows, mirrored along fuselage
 const windowMat=new THREE.MeshStandardMaterial({color:'#27414a',roughness:.24,metalness:.28});const count=data.shape==='jumbo'?30:data.shape==='regional'?14:19;
 for(let side of [-1,1])for(let i=0;i<count;i++){const x=-data.length*.36/s+i*(data.length*.72/s)/(count-1);const w=new THREE.Mesh(new THREE.SphereGeometry(.105,7,5),windowMat);w.scale.set(1,.66,.42);w.position.set(x,.39,side*.88);group.add(w)}
 // gear struts and wheels
 const gear=new THREE.Group();group.add(gear);const gearPoints=[[data.length*.14/s,-3.5,0],[-data.length*.22/s,-3.5,-2.2],[-data.length*.22/s,-3.5,2.2]];
 for(const [x,y,z] of gearPoints){const strut=box(gear,new THREE.CylinderGeometry(.12,.17,2.7,8),dark,[x,y+1.25,z]);for(const side of (Math.abs(z)<.1?[-1,1]:[0])){const tire=new THREE.Mesh(new THREE.CylinderGeometry(.58,.58,.34,12),rubber);tire.rotation.x=Math.PI/2;tire.position.set(x,y,z+side*.4);gear.add(tire)}}
 // door outlines, service panels, navigation lights
 const doorMat=mat('#64777c',.48,.3);for(const x of [-data.length*.25/s,data.length*.25/s])for(const side of [-1,1]){const d=box(group,new THREE.BoxGeometry(2.4,.06,.04),doorMat,[x,0.2,side*.98],[1,1,1],false);d.rotation.z=.03}
 for(const side of [-1,1]){const nav=new THREE.Mesh(new THREE.SphereGeometry(.19,8,6),mat(side===1?'#ef5f53':'#66dc8a',.3,.2));nav.position.set(-wingLen*.84,.03,side*wingLen);group.add(nav)}
 return {group,data,bodyMat,wingMat,accent,engineGroups,gear,damage:100,engineCondition:conditions.engine||'nominal',speed:conditions.speed??data.speed,altitude:conditions.altitude??2500,passengers:conditions.passengers??data.seats,velocity:new THREE.Vector3(),heading:conditions.heading??270,spin:0,alive:true,components:{Nose:100,Cockpit:100,Fuselage:100,'Left wing':100,'Right wing':100,Tail:100,Engines:100,'Landing gear':100},flicker:Math.random()*8};
}

