// Camera orbit and free-fly navigation
let orbitYaw=.62,orbitPitch=.30,orbitDistance=1450,dragging=false,lastX=0,lastY=0,keys={};const focus=new THREE.Vector3(0,0,180);
function positionCamera(){orbitPitch=THREE.MathUtils.clamp(orbitPitch,-.15,1.25);camera.position.set(focus.x+Math.sin(orbitYaw)*Math.cos(orbitPitch)*orbitDistance,focus.y+Math.sin(orbitPitch)*orbitDistance,focus.z+Math.cos(orbitYaw)*Math.cos(orbitPitch)*orbitDistance);camera.lookAt(focus)}positionCamera();
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',e=>{dragging=false;try{canvas.releasePointerCapture(e.pointerId)}catch{}});canvas.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;orbitYaw-=dx*.004;orbitPitch+=dy*.003;positionCamera()});canvas.addEventListener('wheel',e=>{orbitDistance=THREE.MathUtils.clamp(orbitDistance*Math.exp(e.deltaY*.0009),180,4200);positionCamera()},{passive:true});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyF')openModal();if(e.code==='Escape')closeModal();if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault()});window.addEventListener('keyup',e=>keys[e.code]=false);
let touchStart=null;canvas.addEventListener('touchstart',e=>{if(e.touches.length===1)touchStart=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});
// UI and fleet selection
const byId=id=>document.getElementById(id);let selectedFleet=fleet[0];
function buildFleet(){byId('fleetGrid').innerHTML='';fleet.forEach((f,i)=>{const el=document.createElement('button');el.className='fleet-card'+(i===0?' selected':'');el.innerHTML=`<span class="fleet-art">✈</span><strong>${f.name}</strong><small>${f.type}</small><span class="select-check">✓</span>`;el.onclick=()=>{selectedFleet=f;document.querySelectorAll('.fleet-card').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');byId('passengers').max=f.seats;byId('passengers').value=f.seats;byId('passengerValue').textContent=f.seats};byId('fleetGrid').append(el)})}buildFleet();
function openModal(){byId('modalBackdrop').classList.add('open');byId('helpPanel').classList.remove('open')}function closeModal(){byId('modalBackdrop').classList.remove('open')}byId('spawnBtn').onclick=openModal;byId('closeModal').onclick=closeModal;byId('modalBackdrop').addEventListener('click',e=>{if(e.target===byId('modalBackdrop'))closeModal()});
function range(id,output,format){const el=byId(id);el.addEventListener('input',()=>byId(output).textContent=format(+el.value))}range('altitude','altValue',v=>`${v.toLocaleString()} ft`);range('speed','speedValue',v=>`${v} kt`);range('heading','headingValue',v=>`${v}°`);range('condition','conditionValue',v=>`${v}%`);range('passengers','passengerValue',v=>v);
function notify(text){const t=byId('toast');t.textContent=text;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),2300)}
function addAircraft(data,opts={}){const plane=makePlane(data,opts);plane.id=`${data.id}-${String(aircraft.length+1).padStart(2,'0')}`;plane.callSign=opts.callSign||`${['NORTH','PACIFIC','SKY','COAST'][aircraft.length%4]} ${204+aircraft.length*17}`;
 plane.group.position.set(opts.x??(-300+(Math.random()-.5)*140),Math.max(14,(opts.altitude??2500)*.3048),opts.z??(1050+(Math.random()-.5)*140));plane.group.rotation.y=THREE.MathUtils.degToRad(90-(opts.heading??270));
 plane.speed=opts.speed??data.speed;plane.damage=opts.condition??100;plane.components={...plane.components};Object.keys(plane.components).forEach(k=>plane.components[k]=plane.damage);plane.engineCondition=opts.engine||'nominal';plane.passengers=opts.passengers??data.seats;
 if(plane.engineCondition==='degraded')plane.components.Engines=Math.min(plane.components.Engines,62);if(plane.engineCondition==='failed')plane.components.Engines=0;
 if(plane.damage<100){plane.components['Left wing']=plane.damage;plane.components.Fuselage=Math.min(100,plane.damage+5)}
 plane.velocity.set(Math.sin(THREE.MathUtils.degToRad(opts.heading??270))*plane.speed*.514,0,-Math.cos(THREE.MathUtils.degToRad(opts.heading??270))*plane.speed*.514);
 scene.add(plane.group);aircraft.push(plane);setSelected(plane);renderAircraftList();notify(`${data.name.toUpperCase()} PLACED · ${plane.callSign}`);return plane}
byId('confirmSpawn').onclick=()=>{const p=addAircraft(selectedFleet,{altitude:+byId('altitude').value,speed:+byId('speed').value,heading:+byId('heading').value,condition:+byId('condition').value,engine:byId('engineCondition').value,passengers:+byId('passengers').value});focus.copy(p.group.position);focus.y=Math.min(focus.y,800);orbitDistance=670;positionCamera();closeModal()};
function renderAircraftList(){byId('aircraftCount').textContent=String(aircraft.length).padStart(2,'0');const list=byId('aircraftList');if(!aircraft.length){list.innerHTML='<div class="empty-state">No aircraft in range.<br><span>Spawn one to begin.</span></div>';return}list.innerHTML='';aircraft.forEach(p=>{const el=document.createElement('div');el.className='aircraft-row'+(selected===p?' active':'');el.innerHTML=`<span class="plane-thumb">✈</span><div><strong>${p.data.name}</strong><small>${p.callSign} · ${Math.round(p.speed)} KT</small></div><span class="row-health">${Math.round(p.damage)}%</span>`;el.onclick=()=>setSelected(p);list.append(el)})}
function setSelected(p){selected=p;renderAircraftList();renderInspector()}
function renderInspector(){const root=byId('inspectContent');if(!selected){root.className='inspect-empty';root.innerHTML='<div class="reticle">⌖</div><strong>Select an aircraft</strong><span>Click any aircraft in the world<br>to inspect its systems.</span>';return}const p=selected;root.className='inspect-body';const comps=Object.entries(p.components);const degraded=p.damage<65;root.innerHTML=`<div class="inspect-type">${p.data.type}</div><h2>${p.data.name}</h2><div class="inspect-sub">${p.callSign} · ${p.alive?'IN FLIGHT':'DOWNED'}</div><div class="condition-line"><i style="width:${Math.max(0,p.damage)}%;background:${p.damage<35?'#ff775f':p.damage<65?'#ffbc63':'var(--lime)'}"></i></div><div class="condition-meta"><span>AIRFRAME INTEGRITY</span><b>${Math.round(p.damage)}%</b></div><div class="inspect-stats"><div class="stat-line"><span>Altitude</span><b>${Math.max(0,Math.round(p.group.position.y*3.281)).toLocaleString()} FT</b></div><div class="stat-line"><span>Indicated speed</span><b>${Math.max(0,Math.round(p.speed))} KT</b></div><div class="stat-line"><span>Passengers</span><b>${p.passengers}</b></div><div class="stat-line"><span>Engine status</span><b style="color:${p.components.Engines<50?'#ffbc63':'#c8f36b'}">${p.components.Engines===0?'FAILED':p.engineCondition.toUpperCase()}</b></div></div><div class="components"><div class="components-title">SYSTEMS & COMPONENTS</div>${comps.map(([name,value])=>`<div class="component"><span>${name}</span><em class="${value<60?'warn':''}">${value===0?'FAILED':value<60?'DAMAGED':'NOMINAL'}</em></div>`).join('')}</div><div class="action-stack"><button class="action-btn primary" id="controlAction">${controlled===p?'RELEASE CONTROLS':'TAKE CONTROL'}</button><button class="action-btn" id="engineAction">${p.components.Engines===0?'RESTART ENGINE':'ENGINE FAILURE'}</button><button class="action-btn" id="damageAction">${p.damage<100?'RESET AIRFRAME':'APPLY STRUCTURAL DAMAGE'}</button><button class="action-btn" id="deleteAction">REMOVE AIRCRAFT</button></div>`;
 byId('controlAction').onclick=()=>{controlled=controlled===p?null:p;renderInspector();notify(controlled?'PILOT CONTROL ENABLED':'PILOT CONTROL RELEASED')};
 byId('engineAction').onclick=()=>{if(p.components.Engines===0){p.components.Engines=100;p.engineCondition='nominal';notify('ENGINE RESTARTED · NOMINAL')}else{p.components.Engines=0;p.engineCondition='failed';notify('ENGINE FAILURE INJECTED')};renderInspector()};
 byId('damageAction').onclick=()=>{if(p.damage<100){p.damage=100;Object.keys(p.components).forEach(k=>p.components[k]=100);p.alive=true;notify('AIRFRAME RESTORED')}else{damagePlane(p,36);notify('STRUCTURAL DAMAGE APPLIED · 36%');}renderInspector();renderAircraftList()};
 byId('deleteAction').onclick=()=>{scene.remove(p.group);aircraft.splice(aircraft.indexOf(p),1);if(controlled===p)controlled=null;selected=aircraft[0]||null;renderAircraftList();renderInspector();notify('AIRCRAFT REMOVED')};}
// Start with an active demo flight so the simulation is immediately alive.
const demo=addAircraft(fleet[0],{x:-25,z:350,altitude:2350,speed:210,heading:260,callSign:'SKY 208'});demo.group.position.y=2350*.3048;focus.set(0,110,220);

// Simulation events, rescue response, and recorder data
const incidents=[];let rescueUnits=[];function recordEvent(p,text){const at=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'});incidents.unshift({at,flight:p.callSign,text});if(incidents.length>30)incidents.pop()}
function spawnRescue(p){for(let i=0;i<3;i++){const unit=new THREE.Group(),paint=mat(i===0?'#d64c3c':i===1?'#e4d7ab':'#e7e8df',.55,.1),black=mat('#20282b');unit.position.set(p.group.position.x+(Math.random()-.5)*36,1,p.group.position.z+(Math.random()-.5)*36);scene.add(unit);box(unit,new THREE.BoxGeometry(5,2.1,8),paint,[0,1.3,0]);box(unit,new THREE.BoxGeometry(4.5,1.1,2.8),mat('#334b53',.26,.25),[0,2.7,-.3]);for(const x of [-1.6,1.6])for(const z of [-2.5,2.5]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.63,.63,.36,10),black);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.65,z);unit.add(wheel)}const flash=box(unit,new THREE.BoxGeometry(1.4,.22,1),mat(i===0?'#ff3e34':'#54dcff',.2,.15),[0,3.35,0]);rescueUnits.push({group:unit,flash,phase:i*.8,target:p.group.position.clone(),speed:22+i*5})}}
function crashPlane(p,reason='GROUND IMPACT'){if(!p.alive)return;p.alive=false;p.damage=Math.min(p.damage,Math.max(4,p.damage-58));p.components.Fuselage=Math.min(p.components.Fuselage,p.damage);p.components.Cockpit=Math.min(p.components.Cockpit,p.damage);p.components['Landing gear']=0;p.speed=0;p.group.rotation.z=0;recordEvent(p,reason);notify(`${p.callSign} · ${reason} — RESPONSE DISPATCHED`);spawnRescue(p);renderInspector();renderAircraftList();}
function damagePlane(p,amount){p.damage=Math.max(0,p.damage-amount);const keys=Object.keys(p.components);const key=keys[Math.floor(Math.random()*keys.length)];p.components[key]=Math.max(0,p.components[key]-amount);if(key.includes('wing'))p.components[key]=Math.min(p.components[key],p.damage);recordEvent(p,`${key.toUpperCase()} DAMAGE · ${amount}%`);renderInspector()}
let replayUntil=0;function replay(p){focus.copy(p.group.position);orbitDistance=250;orbitPitch=.2;replayUntil=performance.now()+8000;notify('INCIDENT REPLAY · 8 SECOND CINEMATIC');recordEvent(p,'CINEMATIC REPLAY CAPTURED')}
function showRecorder(p){const last=incidents.filter(i=>i.flight===p.callSign);const lines=last.length?last.map(i=>`${i.at}  ${i.text}`).join('\n'):'No incident events recorded. Flight data is nominal.';window.alert(`FLIGHT DATA RECORDER  /  ${p.callSign}\n${p.data.name} · ${p.passengers} souls on board\n\n${lines}\n\nRecorder data stored locally for this session.`)}
// Add the recovery and investigation actions to the inspector controls.
const previousRenderInspector=renderInspector;
// Extend existing inspector render by wrapping it after initial implementation.
renderInspector=function(){previousRenderInspector();if(!selected)return;const stack=document.querySelector('.action-stack');if(!stack)return;const replayButton=document.createElement('button');replayButton.className='action-btn';replayButton.textContent='CINEMATIC REPLAY';replayButton.onclick=()=>replay(selected);const recorder=document.createElement('button');recorder.className='action-btn';recorder.textContent='FLIGHT DATA RECORDER';recorder.onclick=()=>showRecorder(selected);stack.append(replayButton,recorder)};
// Weather cycle: clear / overcast / storm conditions, with a live wind readout.
const weatherSets=[{name:'CLEAR',sky:'#a9c5c6',fog:'#a9c5c6',wind:8},{name:'OVERCAST',sky:'#84999c',fog:'#84999c',wind:18},{name:'SQUALL',sky:'#536a73',fog:'#536a73',wind:32}];byId('weatherBtn').onclick=()=>{weatherMode=(weatherMode+1)%weatherSets.length;const w=weatherSets[weatherMode];scene.background.set(w.sky);scene.fog.color.set(w.fog);sun.intensity=weatherMode===2?1.15:weatherMode===1?2:3.4;byId('windReadout').textContent=String(w.wind).padStart(2,'0');notify(`WEATHER UPDATE · ${w.name} · WIND ${w.wind} KT`)};
byId('soundBtn').onclick=()=>notify('AMBIENT AUDIO · MUTED IN THIS BUILD');byId('helpBtn').onclick=()=>byId('helpPanel').classList.toggle('open');byId('closeHelp').onclick=()=>byId('helpPanel').classList.remove('open');
// Screen picking selects an airframe from the rendered scene.
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let pressPos=null;canvas.addEventListener('pointerdown',e=>pressPos=[e.clientX,e.clientY]);canvas.addEventListener('click',e=>{if(!pressPos||Math.hypot(e.clientX-pressPos[0],e.clientY-pressPos[1])>5)return;const r=canvas.getBoundingClientRect();pointer.set(((e.clientX-r.left)/r.width)*2-1,-((e.clientY-r.top)/r.height)*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(aircraft.flatMap(p=>p.group.children),true);if(hits.length){let obj=hits[0].object;while(obj.parent&&!aircraft.find(p=>p.group===obj))obj=obj.parent;const p=aircraft.find(p=>p.group===obj);if(p){setSelected(p);notify(`${p.callSign} SELECTED`)}}});
// Flight model: lift, drag, mass/inertia, wind, asymmetric damage and ground response.
let previous=performance.now(), elapsed=0;function step(now){const dt=Math.min(.04,(now-previous)/1000||.016);previous=now;elapsed+=dt;
 for(const p of aircraft){const g=p.group;if(p.alive){const pilot=controlled===p;const heading=THREE.MathUtils.degToRad(p.heading);let throttle=pilot?((keys.Space?1:0)-(keys.ShiftLeft||keys.ShiftRight?1:0)):0;
